-- RetainIQ v3 multi-tenant SaaS migration.
-- The application uses SQLAlchemy metadata for local bootstrap; run reviewed migrations in production.
CREATE TABLE IF NOT EXISTS organizations (id SERIAL PRIMARY KEY,name VARCHAR(160) NOT NULL,slug VARCHAR(80) UNIQUE NOT NULL,plan VARCHAR(30) NOT NULL DEFAULT 'starter',is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS memberships (id SERIAL PRIMARY KEY,organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,role VARCHAR(20) NOT NULL DEFAULT 'agent',created_at TIMESTAMP NOT NULL DEFAULT NOW(),UNIQUE(organization_id,user_id));
CREATE TABLE IF NOT EXISTS organization_customers (id SERIAL PRIMARY KEY,organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,customer_id VARCHAR(20) NOT NULL REFERENCES customers(customer_id) ON DELETE CASCADE,assigned_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,lifecycle_status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMP NOT NULL DEFAULT NOW(),UNIQUE(organization_id,customer_id));
CREATE TABLE IF NOT EXISTS prediction_records (id SERIAL PRIMARY KEY,organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,customer_id VARCHAR(20) NOT NULL,created_by INTEGER REFERENCES users(id),probability DOUBLE PRECISION NOT NULL,risk_level VARCHAR(20) NOT NULL,prediction_label VARCHAR(40) NOT NULL,revenue_at_risk DOUBLE PRECISION NOT NULL DEFAULT 0,model_version VARCHAR(80) NOT NULL,explanation_json TEXT,predicted_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS retention_tasks (id SERIAL PRIMARY KEY,organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,customer_id VARCHAR(20),assigned_user_id INTEGER REFERENCES users(id),created_by INTEGER REFERENCES users(id),title VARCHAR(180) NOT NULL,description TEXT,priority VARCHAR(20) NOT NULL DEFAULT 'medium',status VARCHAR(30) NOT NULL DEFAULT 'open',due_at TIMESTAMP,created_at TIMESTAMP NOT NULL DEFAULT NOW(),completed_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS tenant_interactions (id SERIAL PRIMARY KEY,organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id),customer_id VARCHAR(20),channel VARCHAR(30) NOT NULL,subject VARCHAR(160) NOT NULL,notes TEXT,sentiment VARCHAR(20) NOT NULL DEFAULT 'neutral',status VARCHAR(30) NOT NULL DEFAULT 'open',follow_up_at TIMESTAMP,created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS retention_playbooks (id SERIAL PRIMARY KEY,organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,name VARCHAR(160) NOT NULL,description TEXT,trigger_risk VARCHAR(20) NOT NULL,recommended_action TEXT NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS retention_outcomes (id SERIAL PRIMARY KEY,organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,customer_id VARCHAR(20) NOT NULL,recorded_by INTEGER REFERENCES users(id),outcome VARCHAR(40) NOT NULL,revenue_protected DOUBLE PRECISION NOT NULL DEFAULT 0,notes TEXT,recorded_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS data_imports (id SERIAL PRIMARY KEY,organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,uploaded_by INTEGER REFERENCES users(id),filename VARCHAR(255) NOT NULL,row_count INTEGER NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'completed',error_message TEXT,created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs (id SERIAL PRIMARY KEY,organization_id INTEGER REFERENCES organizations(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id),action VARCHAR(100) NOT NULL,entity_type VARCHAR(80),entity_id VARCHAR(80),details_json TEXT,created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS ix_prediction_org_customer ON prediction_records(organization_id,customer_id);
CREATE INDEX IF NOT EXISTS ix_tasks_org_status ON retention_tasks(organization_id,status);
CREATE INDEX IF NOT EXISTS ix_audit_org_created ON audit_logs(organization_id,created_at DESC);
